function humanizeText(value){return String(displayValue(value))
  .replace(/неизменяемая доказательная база/giu,"расчётная основа")
  .replace(/Финансовая конфигурация поддерживает не саму занятость, а способность/gu,"Денежная ценность здесь связана не с самой занятостью, а со способностью")
  .replace(/Конфигурация отношений подчёркивает/gu,"Для вас особенно важны")
  .replace(/несколько реалистичных конфигураций решения/gu,"несколько реалистичных вариантов решения")
  .replace(/Для этой конфигурации содержательнее/gu,"Для вас содержательнее")
  .replace(/общей конфигурации/gu,"общей картины")
  .replace(/Карта не назначает конкретную профессию, но\s*достаточно ясно описывает/gu,"Сочетание признаков ясно описывает")
  .replace(/Это не обещание дохода:\s*расчёт показывает символическую связь денег с интеллектуальным вкладом,\s*а практический результат зависит/gu,"Практический результат зависит")
  .replace(/При этом карта не сообщает дату брака и\s*не описывает неизбежный сценарий\.\s*/gu,"")
  .replace(/Адаптация к непрозрачной среде/gu,"Слишком долго оставаться в непрозрачной среде")
  .replace(/Полировка невидимой части/gu,"Слишком долго улучшать то, чего ещё не видно")
  .replace(/Оформить одну ключевую компетенцию/gu,"Превратить одну ключевую компетенцию в понятный способ работы")
  .replace(/\bmarker\b/giu,"знак")
  .replace(/\.\./gu,".");}
function clean(value,ctx){let text=russianTypography(humanizeText(value).normalize("NFC").replace(/[\u00AD\u200B-\u200D\u2060\uFEFF]/gu,"").replace(/[\uFFFD\uFFFE\uFFFF]/gu,"-").replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/gu,"").replace(/[−‑]/gu,"-").replace(/[ \t]{2,}/gu," ").trim());if(ctx&&!ctx.fonts.cjkReady)text=text.replace(/[\u3400-\u9FFF]+/gu,"").replace(/\s+([,.;:])/gu,"$1").replace(/\s{2,}/gu," ");return text;}
